pub fn lkey_for(
    entity: ControlEntity,
    head: &str,
    classifier: Option<&str>,
    band: Option<&str>,
) -> String {
    let e = entity.as_str();
    match (classifier, band) {
        (None, None) => format!("{e}/h/{head}"),
        (Some(c), None) => format!("{e}/c/{head}/{c}"),
        (None, Some(b)) => format!("{e}/b/{head}/{b}"),
        (Some(c), Some(b)) => format!("{e}/cb/{head}/{c}/{b}"),
    }
